// src/importer.js

const _ = require('lodash');

class RecordsImporter {
  constructor() {
    this.records = [];
    this.duplicates = new Set();
    this.checkpoints = {};
    this.lastCheckpointId = null;
    this.isRunning = false;
    this.errorMessages = [];

    this.importRecords = this.importRecords.bind(this);
    this.checkpoint = this.checkpoint.bind(this);
    this.resume = this.resume.bind(this);
    this.stop = this.stop.bind(this);
  }

  async importRecords(records) {
    if (this.isRunning) return;

    this.isRunning = true;
    try {
      records.forEach(record => {
        const id = record.id || _.uniqueId();

        // Deduplicate by ID
        if (!_.isEqual(_.omitBy(record, r => !r), _.omitBy(this.records.find(r => r.id === id), r => !r))) {
          this.records.push(record);
          this.duplicates.add(id);
        } else {
          throw new Error(`Duplicate record found: ${record}`);
        }
      });

      await this.checkpoint();
    } catch (error) {
      this.errorMessages.push(error.message);
      this.stop();
    } finally {
      this.isRunning = false;
    }
  }

  checkpoint() {
    if (this.isRunning && this.lastCheckpointId !== undefined) {
      this.checkpoints[this.lastCheckpointId] = { records: this.records.slice(), duplicates: [...this.duplicates] };
      this.lastCheckpointId = undefined;
    }
  }

  resume(checkpointId) {
    if (checkpointId in this.checkpoints) {
      this.records = this.checkpoints[checkpointId].records;
      this.duplicates = new Set([...this.checkpoints[checkpointId].duplicates]);
      this.lastCheckpointId = checkpointId;
    }
  }

  stop() {
    this.isRunning = false;
    this.records = [];
    this.duplicates.clear();
    this.checkpoints = {};
    this.lastCheckpointId = null;
    this.errorMessages = [];
  }
}

module.exports = RecordsImporter;
